{"path":"fees.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Support Plans — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f7f3ef;--muted:#6b5c52;--accent:#8a6b4f;--card:#fff;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:var(--muted);background:linear-gradient(180deg, #fbf8f6 0%, var(--bg) 100%);}
    .pattern{position:fixed;inset:0;z-index:-1;opacity:.25;background-image:url('assets/img/pattern.svg');background-repeat:repeat;background-size:240px}
    header{display:flex;justify-content:space-between;align-items:center;padding:1.1rem 1.6rem;background:transparent}
    nav a{margin:0 .5rem;color:var(--muted);text-decoration:none;font-weight:600}
    .container{max-width:920px;margin:1.2rem auto;padding:1rem}
    .hero{background:var(--card);padding:1.2rem;border-radius:12px;box-shadow:0 6px 18px rgba(40,30,20,0.06)}
    .hero h1{margin:0 0 .4rem;color:#3e3128;font-size:1.5rem}
    .hero p{margin:0;color:#58493f}
    .cta{display:inline-block;margin-top:.8rem;padding:.6rem .9rem;background:var(--accent);color:white;border-radius:8px;text-decoration:none}

    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;margin-top:1rem}
    .card{background:var(--card);padding:1rem;border-radius:10px;border:1px solid rgba(100,80,65,0.06)}
    .card h3{margin:.2rem 0 .4rem;color:#3d2f26}
    .price{font-size:1.25rem;color:#2f2520;font-weight:700}
    .muted{color:#7a6a5f;font-size:.95rem}

    .reveal{opacity:0;transform:translateY(18px);transition:opacity .6s ease,transform .6s ease}
    .reveal.is-visible{opacity:1;transform:none}

    .planner{margin-top:1rem;background:linear-gradient(180deg,var(--glass),#fff);padding:1rem;border-radius:10px}
    .planner label{display:block;font-size:.9rem;margin:.45rem 0;color:#3d2f26}
    .planner select,.planner input[type="number"],.planner textarea{width:100%;padding:.5rem;border-radius:8px;border:1px solid #e6deda;background:white}
    .plan-output{white-space:pre-wrap;background:#fff;padding:.8rem;border-radius:8px;border:1px solid #eee;margin-top:.6rem;font-family:monospace;font-size:.95rem}
    .small{font-size:.85rem;color:#6f6259}

    footer{margin-top:1.6rem;padding:1rem;font-size:.85rem;color:#66594f}
    .notes{background:#fff;padding:.8rem;border-radius:8px;border:1px solid #efe6df;margin-top:1rem}

    @media (prefers-reduced-motion:reduce){
      .reveal{transition:none}
    }
  </style>
</head>
<body>
  <div class="pattern" aria-hidden="true"></div>
  <header>
    <div style="font-weight:700;color:var(--accent)">{{BUSINESS_NAME}}</div>
    <nav aria-label="Primary">
      <a href="index.html">Home</a>
      <a href="about.html">Why Work Together</a>
      <a href="specialties.html">Areas</a>
      <a href="fees.html">Support Plans</a>
      <a href="book.html">Book a Visit</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="container">
    <section class="hero reveal">
      <h1>Transparent contributions for ongoing support</h1>
      <p>I offer a membership-style structure and short-term series so you can choose a rhythm that matches your life. No pressure, just clear options and what each includes.</p>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </section>

    <section class="reveal" aria-labelledby="plans-heading">
      <h2 id="plans-heading" style="margin-top:1rem;color:#3e3128">Membership & series options</h2>
      <div class="grid">
        <div class="card">
          <h3>Foundations Series — 6 sessions</h3>
          <div class="price">Equivalent: $110 / session</div>
          <p class="muted">Structured series for a focused goal. Recommended when you want a clear beginning and end.</p>
          <p class="small">Includes: session notes, guided reflections between sessions, scheduling priority for the series window.</p>
        </div>
        <div class="card">
          <h3>Care Membership — Monthly</h3>
          <div class="price">Starting at $75 / session</div>
          <p class="muted">A steady option for ongoing support and maintenance. Monthly contribution with flexible scheduling and email check-ins.</p>
          <p class="small">Includes: 1–4 sessions/month options, short check-in messages, priority scheduling.</p>
        </div>
        <div class="card">
          <h3>Focused Drop-In</h3>
          <div class="price">$125 per session</div>
          <p class="muted">Single sessions for specific concerns or to re-orient. Ideal for occasional troubleshooting or planning ahead.</p>
          <p class="small">Includes: same-day notes and brief resources to try between visits.</p>
        </div>
      </div>
    </section>

    <section class="reveal">
      <h2 style="margin-top:1rem;color:#3e3128">How I frame pricing</h2>
      <div class="notes">
        <p class="small">I offer different rhythms rather than a single program. Some people prefer a bounded series to address a knot; others prefer an ongoing monthly rhythm for steady support. Contribution levels reflect scheduling priority and included brief messaging. If finances are a significant barrier, please mention it when you contact me; I may have limited sliding scale availability.</p>
      </div>
    </section>

    <section class="reveal">
      <h2 style="margin-top:1rem;color:#3e3128">Session Planner</h2>
      <div class="planner" id="planner-fees" aria-labelledby="planner-fees">
        <label for="focus">Primary focus for sessions</label>
        <select id="focus">
          <option value="Anxiety and stress">Anxiety and stress</option>
          <option value="Relationship patterns">Relationship patterns</option>
          <option value="Life transitions">Life transitions</option>
          <option value="Caregiver burnout">Caregiver burnout</option>
          <option value="Mood or motivation">Mood or motivation</option>
          <option value="Other">Other</option>
        </select>

        <label for="frequency">Preferred frequency</label>
        <select id="frequency">
          <option value="Weekly">Weekly</option>
          <option value="Biweekly">Biweekly</option>
          <option value="Monthly">Monthly</option>
          <option value="Short series (6)">Short series (6)</option>
        </select>

        <label for="goal">A specific short-term goal (one line)</label>
        <input id="goal" type="text" placeholder="e.g., Reduce overwhelm during work hours" />

        <label for="notes">Anything else you'd like me to know (optional)</label>
        <textarea id="notes" rows="3" placeholder="Context, prior supports, preferences..."></textarea>

        <button id="build-plan" style="margin-top:.6rem;padding:.6rem .8rem;border-radius:8px;background:var(--accent);color:white;border:none">Create plan summary</button>

        <div class="plan-output" id="plan-output" aria-live="polite"></div>
        <div style="display:flex;gap:.5rem;margin-top:.5rem">
          <button id="copy-plan" style="padding:.5rem .7rem;border-radius:8px;border:1px solid #e5dcd7;background:white">Copy summary</button>
          <a class="cta" href="book.html" style="text-decoration:none;padding:.5rem .7rem;border-radius:8px;background:#5c4a3f;color:white">Request this rhythm</a>
        </div>
      </div>
    </section>

    <footer>
      <div class="notes">
        <strong>Confidentiality & scope:</strong>
        <p class="small">Sessions are confidential within legal and ethical limits. I will discuss limits to confidentiality, recordkeeping, and what to expect in the first session. I do not provide emergency/crisis services. If you are in immediate danger or experiencing a medical emergency, contact local emergency services or go to the nearest emergency room.</p>
        <p class="small">If you need urgent support between sessions, please use local emergency resources or crisis lines. For non-urgent questions about care and availability, contact me at {{EMAIL}} or call {{PHONE}}.</p>
      </div>
    </footer>
  </main>

  <script>
    (function(){
      // Scroll reveal with reduced-motion respect
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const revealEls = document.querySelectorAll('.reveal');
      function show(el){el.classList.add('is-visible')}
      if(prefersReduced){ revealEls.forEach(show); return }
      const obs = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{ if(e.isIntersecting) { show(e.target); obs.unobserve(e.target); } });
      },{threshold:0.12});
      revealEls.forEach(el=>obs.observe(el));

      // Session Planner (fees page)
      const buildBtn = document.getElementById('build-plan');
      const output = document.getElementById('plan-output');
      const copyBtn = document.getElementById('copy-plan');
      function makeSummary(){
        const focus = document.getElementById('focus').value;
        const freq = document.getElementById('frequency').value;
        const goal = document.getElementById('goal').value.trim() || 'Unspecified short-term goal';
        const notes = document.getElementById('notes').value.trim() || 'No additional notes.';
        const summary = [
          'Session Plan — '+(new Date()).toLocaleDateString(),
          'Primary focus: '+focus,
          'Preferred rhythm: '+freq,
          'Short-term goal: '+goal,
          'Additional notes: '+notes,
          '',
          'Suggested next steps:',
          freq.includes('Weekly')?'- Begin with weekly sessions for 6–8 weeks, then reassess.':'- Begin with the selected rhythm and reassess at 6 sessions.',
          '- Use between-session reflections provided by clinician if applicable.',
          '',
          'Contact to request this plan: '+{{""}} + ' '+ '{{EMAIL}}'
        ].join('\n');
        return summary;
      }
      buildBtn.addEventListener('click',()=>{ output.textContent = makeSummary(); });
      copyBtn.addEventListener('click',async ()=>{
        try{
          await navigator.clipboard.writeText(output.textContent);
          copyBtn.textContent = 'Copied';
          setTimeout(()=>copyBtn.textContent='Copy summary',1500);
        }catch(e){
          alert('Copy failed. You can select and copy the text manually.');
        }
      });
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQs — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbf8f6;--text:#58493f;--accent:#8a6b4f}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:var(--text);background:var(--bg)}
    .wrap{max-width:820px;margin:1rem auto;padding:1rem}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{margin:0 .4rem;text-decoration:none;color:var(--text);font-weight:600}
    .hero{background:#fff;padding:1rem;border-radius:10px;box-shadow:0 8px 20px rgba(40,30,20,0.04)}
    .hero h1{margin:0 0 .4rem}
    .faq-list{margin-top:1rem}
    .qa{background:#fff;padding:.8rem;border-radius:8px;margin-bottom:.6rem;border:1px solid #efe6df}
    .question{font-weight:700}
    .answer{margin-top:.4rem;color:#6d5f55}

    .reveal{opacity:0;transform:translateY(14px);transition:opacity .5s ease,transform .5s ease}
    .reveal.is-visible{opacity:1;transform:none}

    .small{font-size:.88rem;color:#6f6259}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div style="font-weight:700;color:var(--accent)">{{BUSINESS_NAME}}</div>
      <nav aria-label="Primary">
        <a href="index.html">Home</a>
        <a href="approach.html">Approach</a>
        <a href="specialties.html">Areas</a>
        <a href="fees.html">Support Plans</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Contact</a>
      </nav>
    </header>

    <main>
      <section class="hero reveal">
        <h1>Questions you might have</h1>
        <p class="small">Below are common questions about how I work, what to expect in sessions, and practical details. If you don't see what you need, reach out at {{EMAIL}}.</p>
      </section>

      <section class="faq-list">
        <div class="qa reveal" id="q1">
          <div class="question">What can I expect in our first meeting?</div>
          <div class="answer">The first session is an opportunity to share the concerns that brought you here, discuss goals, and outline a collaborative plan. We'll also review confidentiality, recordkeeping, and logistics so you know what to expect.</div>
        </div>

        <div class="qa reveal">
          <div class="question">How long is a session and how often do people usually meet?</div>
          <div class="answer">Standard sessions are 50 minutes. Frequency varies — some people meet weekly for a short period, others choose biweekly or a monthly maintenance rhythm. We discuss what fits your needs and schedule.</div>
        </div>

        <div class="qa reveal">
          <div class="question">Do you accept insurance?</div>
          <div class="answer">I am a private-pay clinician. I can provide a receipt (superbill) you may submit to your insurer for reimbursement; please check with your plan for coverage and out-of-network benefits.</div>
        </div>

        <div class="qa reveal">
          <div class="question">What if I’m in crisis between sessions?</div>
          <div class="answer">I do not provide crisis services. If you are at immediate risk of harm, please call local emergency services or go to the nearest emergency room. For urgent help, you can also reach local crisis hotlines. If you’re unsure, contact your primary care or emergency resources.</div>
        </div>

        <div class="qa reveal">
          <div class="question">How is confidentiality handled?</div>
          <div class="answer">Conversations are confidential within legal and ethical limits. I will review exceptions (e.g., risk of harm, legal requirements) in our first session and answer any questions about records and privacy.</div>
        </div>

        <div class="qa reveal">
          <div class="question">What should I do if payment or scheduling becomes difficult?</div>
          <div class="answer">If finances or scheduling are a challenge, please tell me as early as possible. I try to be transparent and work collaboratively to find a feasible plan; limited reduced-contribution spots may be available depending on current capacity.</div>
        </div>

      </section>

      <section class="reveal" style="margin-top:1rem">
        <h2 style="margin-bottom:.4rem">Still unsure? Try the Session Planner</h2>
        <p class="small">If you're deciding between a short series and an ongoing rhythm, use the session planner on the booking page to build a simple plan you can share in your first session.</p>
        <a href="book.html" style="display:inline-block;margin-top:.5rem;padding:.5rem .8rem;border-radius:8px;background:var(--accent);color:white;text-decoration:none">Open the planner</a>
      </section>

      <footer style="margin-top:1.2rem">
        <div class="notes">
          <p class="small"><strong>Scope and boundaries:</strong> Therapy involves exploring thoughts, emotions, and patterns. I support treatment planning within outpatient therapy scope and coordinate referrals when needs exceed what outpatient therapy provides. If you need specialized medical management or emergency care, I will assist in connecting you with appropriate resources.</p>
        </div>
      </footer>
    </main>
  </div>

  <script>
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const revealEls = document.querySelectorAll('.reveal');
      function show(el){el.classList.add('is-visible')}
      if(prefersReduced){ revealEls.forEach(show); return }
      const obs = new IntersectionObserver((entries)=>{ entries.forEach(e=>{ if(e.isIntersecting){ show(e.target); obs.unobserve(e.target); } }); },{threshold:0.12});
      revealEls.forEach(el=>obs.observe(el));
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book a Visit — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f4efe9;--primary:#7a5d45;--muted:#5b4a40}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;background:var(--bg);color:var(--muted)}
    .wrap{max-width:880px;margin:1rem auto;padding:1rem}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{margin:0 .4rem;text-decoration:none;color:var(--muted);font-weight:600}
    .hero{background:#fff;padding:1rem;border-radius:12px;box-shadow:0 8px 24px rgba(30,20,15,0.05)}
    .hero h1{margin:0}
    .content{display:grid;grid-template-columns:1fr 320px;gap:1rem;margin-top:1rem}
    .card{background:#fff;padding:1rem;border-radius:10px}
    .planner{border-radius:8px;padding:.8rem;background:linear-gradient(180deg,#fff,#fbf9f8)}
    label{display:block;margin-top:.5rem;color:#3e3128}
    input,select,textarea{width:100%;padding:.5rem;border-radius:8px;border:1px solid #efe6df}
    button.primary{margin-top:.6rem;padding:.6rem .8rem;border-radius:8px;background:var(--primary);color:white;border:none}
    .plan-output{white-space:pre-wrap;margin-top:.6rem;padding:.8rem;background:#f9f6f3;border-radius:8px;border:1px solid #efe6df;font-family:monospace}
    .reveal{opacity:0;transform:translateY(12px);transition:opacity .5s ease,transform .5s ease}
    .reveal.is-visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div style="font-weight:700;color:var(--primary)">{{BUSINESS_NAME}}</div>
      <nav aria-label="Primary">
        <a href="index.html">Welcome</a>
        <a href="about.html">About</a>
        <a href="specialties.html">Focus</a>
        <a href="fees.html">Plans</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <main>
      <section class="hero reveal">
        <h1>Plan & request a visit</h1>
        <p style="margin:.4rem 0 .6rem;color:#6e5f56">Use the planner to shape a short plan, then send a booking request. I’ll follow up to confirm timing and administrative details.</p>
      </section>

      <div class="content">
        <div class="card reveal">
          <h2 style="margin-top:0">Booking request</h2>
          <form id="booking-form" aria-label="Booking form">
            <label for="name">Your name</label>
            <input id="name" name="name" required />

            <label for="email">Email</label>
            <input id="email" name="email" type="email" required />

            <label for="phone">Phone (optional)</label>
            <input id="phone" name="phone" />

            <label for="when">Preferred days/times</label>
            <input id="when" name="when" placeholder="Weekdays morning, evenings, etc." />

            <label for="message">Message / Brief reason for seeking support</label>
            <textarea id="message" name="message" rows="4"></textarea>

            <button class="primary" type="submit">Send booking request</button>
            <p class="small" style="margin-top:.6rem">I will reply to scheduling and intake steps via email. If you need immediate support, please use local emergency resources.</p>
          </form>
        </div>

        <aside class="card reveal">
          <h3 style="margin-top:0">Session Planner</h3>
          <div class="planner" id="planner-book">
            <label for="focus-b">Primary focus</label>
            <select id="focus-b">
              <option>Anxiety and stress</option>
              <option>Relationships</option>
              <option>Work-life balance</option>
              <option>Transitions</option>
              <option>Trauma recovery</option>
              <option>Other</option>
            </select>

            <label for="freq-b">Suggested rhythm</label>
            <select id="freq-b">
              <option>Weekly</option>
              <option>Biweekly</option>
              <option>Monthly</option>
              <option>Short series (6 sessions)</option>
            </select>

            <label for="goal-b">Short-term objective</label>
            <input id="goal-b" placeholder="One-line goal" />

            <label for="notes-b">Notes</label>
            <textarea id="notes-b" rows="3"></textarea>

            <button id="build-book-plan" style="margin-top:.6rem;padding:.5rem .7rem;border-radius:8px;background:var(--primary);color:white;border:none">Build plan</button>
            <div class="plan-output" id="plan-output-book" aria-live="polite"></div>
            <div style="display:flex;gap:.5rem;margin-top:.5rem">
              <button id="copy-book" style="padding:.5rem .7rem;border-radius:8px;border:1px solid #efe6df;background:white">Copy</button>
              <button id="paste-into-form" style="padding:.5rem .7rem;border-radius:8px;background:#e8dfd6;border:none">Paste to message</button>
            </div>
          </div>
        </aside>
      </div>

      <section class="reveal" style="margin-top:1rem">
        <div class="card">
          <h3 style="margin-top:0">What happens after you request</h3>
          <p class="small">I will review your request and reply with available times and intake paperwork. Scheduling is confirmed after intake paperwork and a brief administrative check. If we determine a different level of care would be more helpful, I will discuss referrals.</p>
        </div>
      </section>

      <footer style="margin-top:1rem">
        <div class="card">
          <strong>Confidentiality & crisis guidance</strong>
          <p class="small">Communication about scheduling and intake is confidential. Outpatient therapy does not replace emergency services. If you are at immediate risk, contact emergency services or the nearest emergency room. For non-urgent availability questions, reach me at {{EMAIL}} or call {{PHONE}}.</p>
        </div>
      </footer>
    </main>
  </div>

  <script>
    (function(){
      // Reveal
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const revealEls = document.querySelectorAll('.reveal');
      function show(el){el.classList.add('is-visible')}
      if(prefersReduced){ revealEls.forEach(show); }
      else{
        const obs = new IntersectionObserver((entries)=>{ entries.forEach(e=>{ if(e.isIntersecting){ show(e.target); obs.unobserve(e.target);} }); },{threshold:0.12});
        revealEls.forEach(el=>obs.observe(el));
      }

      // Planner logic for booking page
      const build = document.getElementById('build-book-plan');
      const out = document.getElementById('plan-output-book');
      const copy = document.getElementById('copy-book');
      const pasteBtn = document.getElementById('paste-into-form');
      function make(){
        const focus = document.getElementById('focus-b').value;
        const freq = document.getElementById('freq-b').value;
        const goal = document.getElementById('goal-b').value.trim() || 'Not specified';
        const notes = document.getElementById('notes-b').value.trim() || 'None';
        const summary = ['Session Plan Request — '+new Date().toLocaleDateString(),
          'Focus: '+focus,
          'Rhythm: '+freq,
          'Short goal: '+goal,
          'Notes: '+notes,
          '',
          'Preferred contact: '+('Email: {{EMAIL}} | Phone: {{PHONE}}'),
        ].join('\n');
        return summary;
      }
      build.addEventListener('click',()=>{ out.textContent = make(); });
      copy.addEventListener('click',async ()=>{
        try{ await navigator.clipboard.writeText(out.textContent); copy.textContent='Copied'; setTimeout(()=>copy.textContent='Copy',1400); }
        catch(e){ alert('Unable to copy. Select the text and copy manually.'); }
      });
      pasteBtn.addEventListener('click',()=>{
        const formMsg = document.getElementById('message');
        formMsg.value = out.textContent || '';
        formMsg.focus();
      });

      // Booking form submit (placeholder - local only)
      const form = document.getElementById('booking-form');
      form.addEventListener('submit',(e)=>{
        e.preventDefault();
        const name = document.getElementById('name').value.trim() || 'Unknown';
        alert('Thank you, '+name+'. Your request has been noted. I will respond by email regarding next steps.');
        form.reset();
      });
    })();
  </script>
</body>
</html>"} 
